    const colsXml = colWidths.length ? "<cols>".concat(colWidths.map((w, i)=>'<col min="'.concat(i + 1, '" max="').concat(i + 1, '" width="').concat(w, '" customWidth="1"/>')).join(""), "</cols>") : "";
