    const td = "border:1px solid #999;padding:5px;font-size:9.5pt;";
    let head = "<tr>".concat([
        "S/N",
        "NAME",
        "CLASS",
        "GENDER",
        "LIN"
    ].map((h)=>'<th style="'.concat(th, '">').concat(h, "</th>")).join(""), "</tr>");
    let body = "";
    rows.forEach((s, i)=>{
        const rowBg = i % 2 === 0 ? "#ffffff" : "#eff6ff";
        body += '<tr style="background:'.concat(rowBg, ';">');
        body += '<td style="'.concat(td, 'text-align:center;">').concat(i + 1, "</td>");
        body += '<td style="'.concat(td, 'text-align:left;font-weight:600;">').concat(escapeHtml(s.name), "</td>");
        body += '<td style="'.concat(td, 'text-align:center;">').concat(escapeHtml(s.className), "</td>");
        body += '<td style="'.concat(td, 'text-align:center;">').concat(s.gender === "M" ? "Male" : "Female", "</td>");
        body += '<td style="'.concat(td, 'text-align:center;">').concat(escapeHtml(s.lin || "-"), "</td>");
        body += "</tr>";
    });
    const table = '<table style="border-collapse:collapse;width:100%;">'.concat(head).concat(body, "</table>");
    const scopeLabel = "".concat(filterCls === "All" ? "All Classes" : filterCls).concat(filterGender === "All" ? "" : " — ".concat(filterGender === "M" ? "Males" : "Females"));
    let bodyHtml = '<div style="text-align:center;">';
    bodyHtml += '<div class="title">'.concat(escapeHtml((school === null || school === void 0 ? void 0 : school.name) || ""), "</div>");
    if (school === null || school === void 0 ? void 0 : school.motto) bodyHtml += '<div class="motto">"'.concat(escapeHtml(school.motto), '"</div>');
